            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "جوعان يأكل من زادي ويمسكني لكي يقال عظيم القدر مقصود", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "ذو العقل يشقى في النعيم بعقله وأخو الجهالة في الشقاوة ينعم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "تريدين لقيان المعالي رخيصة ولا بد دون الشهد من إبر النحل", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "ما كل ما يتمناه المرء يدركه تجري الرياح بما لا تشتهي السفن", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "إذا أنت أكرمت الكريم ملكته وإن أنت أكرمت اللئيم تمردا", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "وعذلت أهل العشق حتى ذقته فعجبت كيف يموت من لا يعشق", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "وعرفت ذنبي في الهوى أنني عيرت هم فلقيت منه ما لقوا", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "ما باله لاحظته فتضرّجت وجناته وفؤادي المجروح", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "ورمى وما رمته يداه فأصابني سهم يعذب والسهام تريح", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "بفرع يعيد الليل والصبح نير  ووجه يعيد الصبح والليل مظلم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "ومتى تزُر قوم من تهوى زيارتها لا يتحفوك بغير البيض والأسل", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "والهجر أقـتل لي مما أراقبه أنا الغريق فما خوفي من البلل", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "لك يا منازل في القلوب منازل أقفـرت أنت وهن منك أواهـل", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "وقيدت نفسي في ذراك محبة ومن وجد الإحسان قيداً تقيدا", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "إذا الجود لم يرزق خلاصا من الأذى فلا الحمد مكسوبا ولا المال باقيا", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "عش عزيزا أو مت وأنت كريم بين طعن القنا وخفق البنود", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "فاظلب العز في لظى ودع الذل ولو كان في جنان الخلود", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "وزائرتي كأن بها حياء فليس تزور إلا في الظلام", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "بذلت لها المطارف والحشايا فعافتها وباتت في عظامي", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "من يهـن يسهـل الهـوان عليـه ما لجرح بميـت إيـلام", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "إذا غامرت في شرف مروم فلا تقنع بما دون النجوم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "إذا أنت أكرمت الكريم ملكته وإن أنت أكرمت اللئيم تمردا", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "وإذا لم يكن من الموت بدٌ فمن العجز أن تموت جبانا", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "أعز مكان في الدنى سرج سابح وخير جليس في الأنام كتاب", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "خير المحادث والجليس كتاب تخلو به إن ملّك الأصحاب", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "الرأي قبل شجاعة الشجعان هو أول وهي المحل الثاني", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "إذا ساء فعل المرء ساءت ظنونه  وصدق ما يعتدّه من توهم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "حرّض بنيك على الآداب في الصّغر  كيما تقرّ بهم عيناك في الكبر", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "شر البلاد مكان لا صديق به  وشر ما يكسب الإنسان ما يصم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "ومن نكد الدّنيا على الحرّ أن يرى  عدوًا له ما من صداقته بد", Author = "المتنبي" },
